using System;
using System.Collections;
using DG.Tweening;
using LittleLeo.Variables;
using NaughtyAttributes;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class OmenInstance : ZoomableInstance
{
	[Header("Tooltip Up Alignment")]
	[SerializeField]
	protected bool tooltipUpAlignment;

	[Header("Components")]
	[SerializeField]
	private Image omenImage;

	[SerializeField]
	private TextMeshProUGUI omenCounterText;

	[SerializeField]
	[HideIf("compendium")]
	private DOTweenAnimation omenImageDOTween;

	[SerializeField]
	[HideIf("compendium")]
	private DOTweenAnimation backgroundImageDOTween;

	[Header("Feedback")]
	[SerializeField]
	[HideIf("compendium")]
	private GameObject omenFeedbackPrefab;

	[SerializeField]
	[HideIf("compendium")]
	private GameObjectReference playerGameObjectReference;

	[Header("Action Description Panel Positioning")]
	[SerializeField]
	protected bool positionOverride;

	[SerializeField]
	[ShowIf("positionOverride")]
	protected TransformPositionOverride[] transformPositionOverrides;

	[Header("Compendium")]
	[SerializeField]
	private bool compendium;

	protected OmenData omenData;

	private Coroutine newFeedbackDelay;

	private bool ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle;

	public TextMeshProUGUI OmenCounterText => omenCounterText;

	public bool Compendium => compendium;

	public OmenData OmenData => omenData;

	public void SetIgnoreStartOfTurnUpdateOmenCounterForTheRestOfBattle(bool ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle)
	{
		this.ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle = ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle;
	}

	public void Initialize(OmenData omenData, int omenCounter = 0)
	{
		EnableOmen();
		omenImage.sprite = omenData.OmenSprite;
		if (omenData.MuteForMod && compendium)
		{
			omenImage.color = new Color(0.3f, 0.3f, 0.3f);
		}
		if (omenData.EnableColorMask)
		{
			omenImage.material = omenData.omenSpriteColorMask;
		}
		else
		{
			omenImage.material = null;
		}
		this.omenData = omenData;
		omenData.SetCounter(omenCounter);
		UpdateOmenCounter();
	}

	public override void InitializeActionDescriptionPanel()
	{
		if (positionOverride)
		{
			actionDescriptionPanel.OverridePositions(transformPositionOverrides);
		}
		omenData.InitializeActionDescriptionPanel();
		actionDescriptionPanel.InitializeOmenInstance(omenData, tooltipUpAlignment, !tooltipUpAlignment, this);
	}

	public void DestroyOmen(Action afterShakeAction)
	{
		CoroutineUtility.ShakeRoutine(this, base.transform, afterShakeAction);
	}

	public void ActivateOmenFeedback()
	{
		PlayOmenShakeFeedback();
		ReferenceSingleton<PoolHandler>.Instance.GetObject(omenFeedbackPrefab.name).GetComponent<OmenEffectFeedback>().PlayOmenFeedback(omenData, playerGameObjectReference.value.transform.position);
	}

	public void EnqueueOmenFeedbackAndPlay()
	{
		if (newFeedbackDelay == null)
		{
			newFeedbackDelay = StartCoroutine(NewFeedbackDelayCoroutine());
			playerGameObjectReference.value.GetComponent<UnitFeedbackHandler>().EnqueueOmenFeedbackAndPlay(delegate
			{
				CoroutineUtility.ShakeRoutine(this, base.transform);
				ReferenceSingleton<PoolHandler>.Instance.GetObject(omenFeedbackPrefab.name).GetComponent<OmenEffectFeedback>().PlayOmenFeedback(omenData, playerGameObjectReference.value.transform.position);
			});
		}
	}

	private IEnumerator NewFeedbackDelayCoroutine()
	{
		yield return new WaitForSeconds(0.1f);
		newFeedbackDelay = null;
	}

	public void PlayOmenShakeFeedback()
	{
		CoroutineUtility.ShakeRoutine(this, base.transform);
	}

	public void ToggleOmenCounter(bool toggle)
	{
		omenCounterText.gameObject.SetActive(toggle);
	}

	public void UpdateOmenCounter()
	{
		if (!ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle)
		{
			if (omenData.EnableOmenCounter && !omenData.DisableOmenCounterText)
			{
				ToggleOmenCounter(toggle: true);
				omenCounterText.SetText(omenData.Counter.ToString());
			}
			else
			{
				ToggleOmenCounter(toggle: false);
			}
		}
	}

	public void PlayBlinkingFeedback()
	{
		omenImageDOTween.DOPlay();
		backgroundImageDOTween.DOPlay();
	}

	public void StopBlinkingFeedback()
	{
		omenImageDOTween.DORewind();
		backgroundImageDOTween.DORewind();
	}

	public void DisableOmen()
	{
		StopBlinkingFeedback();
		omenImage.color = new Vector4(0.3f, 0.3f, 0.3f, 1f);
	}

	public void EnableOmen()
	{
		omenImage.color = new Vector4(1f, 1f, 1f, 1f);
	}
}
